input.command:
cd /workspace
cat > /tmp/setup.sql <<'EOF'
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE raw_list AS
SELECT * FROM read_csv('lists/goias-sample.csv', header=true, columns={'cod_imovel':'VARCHAR','municipio':'VARCHAR','cod_estado':'VARCHAR','geometry':'VARCHAR'});
SELECT count(*) AS total_rows,
       count(*) FILTER (WHERE cod_imovel IS NOT NULL AND cod_imovel<>'') AS id_rows,
       count(*) FILTER (WHERE geometry IS NOT NULL AND geometry<>'') AS geom_rows,
       count(*) FILTER (WHERE (cod_imovel IS NULL OR cod_imovel='')) AS idless_rows
FROM raw_list;
SELECT '--- exact dup lines ---';
SELECT cod_imovel, municipio, geometry, count(*) c FROM raw_list GROUP BY ALL HAVING count(*)>1;
SELECT '--- geom rows ---';
SELECT rowid, cod_imovel, ST_GeometryType(ST_GeomFromText(geometry)) gt, geometry[1:40] FROM raw_list WHERE geometry IS NOT NULL AND geometry<>'';
EOF
timeout 120 duckdb /workspace/work.duckdb < /tmp/setup.sql 2>&1 | head -60

cd /workspace
cat > /tmp/car.sql <<'EOF'
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
-- distinct listed IDs
CREATE OR REPLACE TABLE listed_ids AS
SELECT DISTINCT cod_imovel FROM raw_list WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
SELECT count(*) AS n_distinct_listed_ids FROM listed_ids;
-- pull CAR rows for listed IDs (may be multiple rows per id)
CREATE OR REPLACE TABLE car_listed AS
SELECT cod_imovel, municipio, cod_estado, num_area, geometry
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
WHERE cod_imovel IN (SELECT cod_imovel FROM listed_ids);
SELECT count(*) AS car_rows, count(DISTINCT cod_imovel) AS car_ids FROM car_listed;
EOF
timeout 900 duckdb /workspace/work.duckdb < /tmp/car.sql 2>&1 | tail -30

