cd /workspace
cat > /tmp/insp.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE mf AS
SELECT fm.field_id, fm.primary_cod, fm.area_ha,
  CAST(fld.mbmode24 AS INTEGER) AS mbmode24,
  fld.deforestarea0104/10000.0 AS e1, fld.deforestarea0509/10000.0 AS e2,
  fld.deforestarea1014/10000.0 AS e3, fld.deforestarea1520/10000.0 AS e4,
  fld.deforestarea2124/10000.0 AS e5,
  CAST(fld.mode_year AS INTEGER) AS mode_year, CAST(fld.firstyear AS INTEGER) AS firstyear,
  CAST(fld.firstyearmajority AS INTEGER) AS firstyearmajority
FROM field_match fm JOIN fields fld ON fld.field_id=fm.field_id
WHERE fm.matched;
SELECT count(*) matched, count(DISTINCT primary_cod) parcels FROM mf;
SELECT 'mbmode24 dist'; SELECT mbmode24, count(*) n, round(sum(e5),3) post2020 FROM mf GROUP BY mbmode24 ORDER BY n DESC;
SELECT 'mode_year dist for fields w/ post2020 loss'; SELECT mode_year, count(*) n FROM mf WHERE e5>0 GROUP BY mode_year ORDER BY mode_year;
EOF
